// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":1061,"question":"هل سجود التِّلاوة فيه تسليمٌ أم لا؟","title":"هل يُشرع التسليم من سجود التِّلاوة؟","answer":"الجواب:\nالصواب أنه ليس فيه تسليمٌ ولا تكبيرٌ ثانٍ، ليس فيه إلا التكبير الأول عند السجود، ويقول فيه ما يقول في الصلاة من تسبيحٍ ودعاءٍ: \"سبحان ربي الأعلى، سبحان ربي الأعلى، اللهم لك سجدتُ، وبك آمنتُ، ولك أسلمتُ، سجد وجهي للذي خلقه وصوَّره وشقَّ سمعه وبصره بحوله وقوته، تبارك الله أحسن الخالقين\"، مثلما يقول في سجود الصلاة. وهو سنة، ليس بواجبٍ، يُكبر عند السجود فقط، إلا إذا كان في الصلاة؛ فإنه يُكبِّر عند السجود وعند الرفع، مثل بقية سجود الصلاة، يُكبِّر عند الخفض والرفع، أما في خارج الصلاة فإنه يُكبِّر عند السُّجود فقط؛ لأنَّ هذا هو الذي جاء في الحديث. وذهب بعضُ أهل العلم إلى أنه يُكبِّر عند الرفع ويُسلِّم، ولكنه ليس عليه دليلٌ.","link":"https://binbaz.org.sa/fatwas/21122/هل-يشرع-التسليم-من-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0918هل سجود التلاوة فيه تسليم أو لا؟ ابن باز فتاوى المحاضرات.mp3","categories":["سجود التلاوة والشكر"]},{"id":1322,"question":"إذا قرأت السجدة لها تكبيرة؟","title":"هل للسجود خارج الصلاة تكبير وتسليم؟","answer":"الجواب:\nمثل سجود الصلاة يقول: سبحان ربي الأعلى، سبحان ربي الأعلى.\nس: لها تسليم؟\nج: لا، ما لها تسليم خارج الصلاة، ما فيها تسليم، يُكَبِّر بس أول ما يسجد، ويكفي.","link":"https://binbaz.org.sa/fatwas/21413/هل-للسجود-خارج-الصلاة-تكبير-وتسليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للسجود خارج الصلاة تكبير وتسليم.mp3","categories":["سجود التلاوة والشكر"]},{"id":1973,"question":"بالنسبة لسجود التلاوة ما كيفيته؟","title":"كيفية سجود التلاوة والشكر وحكمهما","answer":"الجواب:\nمثل سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم..، فتدعو فيه.\nس: هل فيه تكبير عند إرادة السجود؟\nج: في الصلاة: يُكبِّر عند السجود وعند الرفع، أما خارج الصلاة فيُكبِّر عند السجود فقط، أما التكبير عند السجود والرفع فلم يرد فيه شيء.\nس: هل في التلاوة سلام؟\nج: خارج الصلاة ليس هناك شيء، يُكبِّر فقط عند السجود، ويرفع بالقراءة من دون سلامٍ ومن دون تكبيرٍ، أما في السجود في الصلاة فيُكبِّر عند الخفض، ويُكبِّر عند الرفع، مثل سجود الصلاة، إذا كان في داخل الصلاة.\nس: سجود الشكر؟\nج: مثل سجود الصلاة، ومثل سجود التلاوة.\nس: بالنسبة لهذه السَّجدات -التلاوة والشُّكر- ما حكمها؟\nج: مستحبّ.","link":"https://binbaz.org.sa/fatwas/22089/كيفية-سجود-التلاوة-والشكر-وحكمهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية سجود التلاوة وسجود الشكر وحكمها.mp3","categories":["سجود التلاوة والشكر"]},{"id":2485,"question":"هل كان النبي ﷺ في صلاة لما شَفَع لأمته؟","title":"ما دليل سجود الشكر وكيفيته؟","answer":"الجواب:\nفي غير الصلاة، سجود الشكر يسجد الإنسان حتى ولو ما هو على وضوء على الصحيح، سجود الشكر، سجود التلاوة مستحب ولو كانت على غير طهارة.\nس: يرفع بعد السجود كالتكبيرة في الصلاة؟\nالشيخ: ما لزوم تكبير، إن كبر عند السجود فحسن إن شاء الله عند السجود.\nس: حديث سعد بن أبي وقاص صحيح؟\nالشيخ: ما تعرض له المؤلف، سكت عنه المؤلف، لكن السجود ثابت عن النبي ﷺ الشكر.\nس: في نسخة تحقيق الشيخ ناصر الدين الألباني يقول: حديث السجود  ضعيف سندًا ومتنًا؟\nالشيخ: يحتاج تأمل؛ لأنه قد يغلط، غفر الله لنا وله، قد يغلط.\nس: الحديث صحيح؟\nالشيخ: لكن له شواهد في حديث آخر: إذا جاء أمر يَسُرُّه سجد لله عليه الصلاة والسلام.\nس: له صيغة؟\nالشيخ: مثل سجود الصلاة، سجود التلاوة وسجود الشكر مثل سجود الصلاة.\nس: يستقبل القبلة؟\nالشيخ: أفضل، السنة استقبال القبلة إذا تيسر ذلك.","link":"https://binbaz.org.sa/fatwas/22614/ما-دليل-سجود-الشكر-وكيفيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سجود النبي عليه الصلاة والسلام شكرا لله.mp3","categories":["سجود التلاوة والشكر"]},{"id":2486,"question":"سجود التلاوة الأفضل يقوم ثم يخر ساجدًا؟","title":"ما السُّنة في سجود التلاوة والشكر؟","answer":"الجواب:\nلا، يُكَبِّر وهو جالس ويسجد، يكفي الحمد لله.\nس: يُكَبِّر؟\nالشيخ: أفضل، عند السجود بس، عند الهُوِيِّ.\nس: ولو كان على غير طهارة؟\nالشيخ: الصحيح ولو كان على غير طهارة.\nس: هل له دعاء معين؟\nالشيخ: مثل سجود الصلاة، ويحمد ربه ويثني عليه ويدعوه جل وعلا، ويقول: سبحان ربي الأعلى، سبحان ربي الأعلى.\nس: مرة واحدة؟\nالشيخ: على حسب ما تيسر، مرة أو أكثر، كلما جاءه أمر يَسُرُّه، الحمد لله. س: هل يُسلِّم؟ الشيخ: ما فيه سلام ولا تكبيرة ثانية. س: إذا جاءه ما يَسُرُّه من أمور الدنيا والآخرة وإلا من أمور الآخرة فقط؟ الشيخ: من الأمور التي تنفع المسلمين، تسر المسلمين تنفعهم.\nس: إذا جاءه ولده؟\nالشيخ: هذا ينفع هذا مما يسره.","link":"https://binbaz.org.sa/fatwas/22616/ما-السنة-في-سجود-التلاوة-والشكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سجود الشكر وبعض ما يتعلق به.mp3","categories":["سجود التلاوة والشكر"]},{"id":3561,"question":"قراءة السجدة في الصلاة السرية؟","title":"حكم قراءة الإمام آية سجدة في صلاة سرية","answer":"الجواب: إذا قرأها لا يسجد، لا يشوش على الناس.\nس: أحسن الله إليك إمام يقول: قرأت وبها سجدة، ولما وصلت السجود رفعت صوتي في الميكرفون قليلا، ثم سمعوا وسجدوا ورائي؟\nالشيخ: ما كان ليسجد فيها في السرية، السنة ألا يقرأ بها، وإن قرأ بها فلا يسجد؛ لا يشوش على الناس.","link":"https://binbaz.org.sa/fatwas/23743/حكم-قراءة-الامام-اية-سجدة-في-صلاة-سرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قراءة السجدة في الصلاة السرية.mp3","categories":["سجود التلاوة والشكر","صلاة الجماعة"]},{"id":3562,"question":"لو أن الإمام نسى السجود في قراءته يُسبّح المأمومين؟","title":"ما الحكم لو نسي الإمام سجود التلاوة؟","answer":"الجواب: سنة، ما هو بلازم.","link":"https://binbaz.org.sa/fatwas/23744/ما-الحكم-لو-نسي-الامام-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سجود التلاوة في الصلاة.mp3","categories":["سجود التلاوة والشكر"]},{"id":3580,"question":"بعض الأئمة إذا رفع من سجدة التلاوة كبّر، وبعضهم يشرع في القراءة مباشرة دون تكبير؟","title":"هل يُكبَّرللرفع من سجدة التلاوة في الصلاة؟","answer":"الجواب: لا، السنة التكبير إن كان في الصلاة، النبي كان يكبّر في كل خفض ورفع، إذا سجد للتلاوة في الصلاة مثل سجود الصلاة يكبّر عند السجود، ويكبّر عند الرفع إذا كان في الصلاة.","link":"https://binbaz.org.sa/fatwas/23762/هل-يكبرللرفع-من-سجدة-التلاوة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكبر إذا رفع من سجدة التلاوة في الصلاة.mp3","categories":["سجود التلاوة والشكر"]},{"id":5558,"question":"يعني من السُّنة إذا أتى الإنسانَ خبرٌ يسرُّه وهو جالس أن يقوم، أو مُضطجع أن يقوم؟","title":"ما السُّنة إذا أتى الإنسانَ خبرٌ يسرُّه؟","answer":"الجواب: يسجد لله، ولا يشترط له الطَّهارة، سجود الشكر وسجود التلاوة لا يُشترط له الطَّهارة، بخلاف سجود السَّهو فلا بدَّ من الطَّهارة، أما سجود الشُّكر فهو يأتي على غرَّةٍ، فلا مانع من السجود، وهكذا سجود التلاوة وإن كان على غير طهارةٍ، كما جرى للنبي ﷺ وللصحابة  وأرضاهم. س: لكن هل يقوم لو كان مُضطجعًا كما هنا أتاه بشيرٌ؟ ج: يقوم ويسجد. س: لكن لو كان جالسًا أو مُضطجعًا –يعني- يستوي جالسًا ويسجد؟ ج: الظاهر أنه قام من اضطجاعه، ما هو مقصوده أنه قام واقفًا، يعني: قام من مُضطجعه وسجد لله شكرًا. س: ما جاء عن عائشةَ أنَّ الإنسان إذا أراد أن يسجد للتلاوة: أنَّ الأوْلى أن يقوم ثم يسجد عن قيامٍ؟ ج: المعروف أنه كان يسجد وهو جالس عليه الصلاة والسلام. س: الخرور ما يكون عن قيامٍ؟ ج: ما هو بلازمٍ عن قيامٍ، إذا تلا وهو جالس سجد وهو جالس، وإذا تلا وهو قائم خرَّ ساجدًا. س: يعني مَن قال بهذا لي على قولهم دليل؟ ج: ما أعلم دليلًا واضحًا على هذا.[1]","link":"https://binbaz.org.sa/fatwas/31510/ما-السنة-اذا-اتى-الانسان-خبر-يسره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 021.mp3","categories":["سجود التلاوة والشكر"]},{"id":5901,"question":"ما حكم تكبيرة الانتقال في سجدة التلاوة في الصلاة، مع ذكر الدليل؟","title":"حكم تكبيرة الانتقال في سجود التلاوة","answer":"الجواب: سجدة التلاوة مثل سجود الصلاة، إذا سجد يكبر، وإذا رفع يكبر، والدليل على هذا ما ثبت عن رسول الله -عليه الصلاة والسلام- أنه كان في الصلاة يكبر في كل خفض، ورفع إذا سجد كبر، وإذا نهض كبر، هكذا أخبر الصحابة  من حديث أبي هريرة، وغيره، وهذا السجود من سجود الصلاة، فإذا سجد للتلاوة؛ كبر، وإذا رفع من السجدة؛ كبر، هذا هو الأظهر من الأدلة. أما في خارج الصلاة، إذا سجد للتلاوة في خارج الصلاة؛ فلم يرو إلا التكبير في الأول، هذا المعروف، كما رواه أبو داود والحاكم، التكبير في أوله، في أول السجود فقط، أما عند الرفع في خارج الصلاة فلم يرو فيه تكبير، ولا تسليم، وبعض أهل العلم قال: يكبر للنهوض، ويسلم أيضًا، ولكن لم يرد في هذا شيء، فلا يلزمه إلا التكبيرة الأولى التي عن السجود إذا كان خارج الصلاة، أما في داخل الصلاة فإن حكم السجود فيها كبقية سجداتها، يكبر عند الخفض، ويكبر عند الرفع في آخر الصلاة، والله أعلم.","link":"https://binbaz.org.sa/fatwas/1256/حكم-تكبيرة-الانتقال-في-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_252.mp3","categories":["سجود التلاوة والشكر"]},{"id":6078,"question":"قال بعض العلماء: سجدة سورة (ص) سجدة شكر تفعل خارج الصلاة، وإذا سجد داخلها؛ بطلت، فهل هذا صحيح؟","title":"حكم سجدة سورة (ص) في الصلاة وخارجها","answer":"الجواب: نعم سجدة (ص) سجدة شكر، لا شك، لكن من فرق بين الصلاة، وخارجها؛ فليس كلامه صحيحًا، بل الصواب: أنها تفعل في الصلاة، وخارجها، ومن قال: لا تفعل في الصلاة؛ فقد غلط، وقد صلى النبي -عليه الصلاة والسلام- في (ص) وسجد فيها، وهو على المنبر، عليه الصلاة والسلام. فمن قرأها السنة أن يسجد، سواء كان في الصلاة في الفريضة، أو التراويح، أو كان في خارج الصلاة، السنة له أن يسجد مطلقًا حتى في الصلاة، ومن قال: إنها تبطل الصلاة.. فهو قول غلط، لا وجه له في الشرع مطلقًا.","link":"https://binbaz.org.sa/fatwas/1490/حكم-سجدة-سورة-ص-في-الصلاة-وخارجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_420.mp3","categories":["سجود التلاوة والشكر"]},{"id":7591,"question":"سؤال الأخت من تعز الثالث تقول: إذا قرأت المرأة القرآن ثم وصلت عند آية سجود مثل: وَاسْجُدْ وَاقْتَرِبْ [العلق:19] هل يجب عليها أن تسجد، وهل يجوز عند الركوع والسجود أن أزيد التسبيح عن ثلاث مرات؟","title":"حكم سجود التلاوة والزيادة على ثلاث في تسبيح الركوع والسجود","answer":"الجواب: سجود التلاوة ليس بواجب هو سنة، إذا قرأ آيات التلاوة يستحب له السجود إذا قرأ آخر اقرأ، أو آخر النجم: فَاسْجُدُوا لِلَّهِ وَاعْبُدُوا [النجم:62]، أو آخر سورة الأعراف يسجد، هذا السنة، وهكذا بقية السجدات يكبر ويسجد إذا كان خارج الصلاة، وإذا كان في الصلاة يكبر عند سجوده ويكبر عند رفعه في الصلاة، هذه سنة وليست واجبة، ثبت عنه ﷺ أنه قرأ عليه زيد بن ثابت سورة النجم فلم يسجد فيها، فدل ذلك على أن السجود ليس بواجب، وقال عمر : إن الله لم يفرض السجود إلا أن نشاء.\nالحاصل: أن سجود التلاوة مستحب وسنة وليس بواجب، فمن سجد فله أجر، ومن ترك فلا إثم عليه، والحمد لله. \nالشيخ: ما قبله؟ أعد سؤالها.\nالمقدم: هذا الثالث؟\nالشيخ: إيه.\nالمقدم: إذا قرأت المرأة القرآن ثم وصلت عند آية السجود مثل: وَاسْجُدْ وَاقْتَرِبْ [العلق:19]، هل يجب عليها أن تسجد، وهل يجوز عند الركوع أو السجود أن أزيد التسبيح عن ثلاث مرات؟ \nالشيخ: كذلك لا بأس بالزيادة، التسبيح في الركوع والسجود بل أفضل، أدنى الكمال ثلاث مرات، ولكن إذا زاد على ذلك فسبح أربعاً أو خمساً أو سبعاً كان أفضل وأكثر طمأنينة، فالثلاث أدنى الكمال، والواجب مرة؛ سبحان ربي العظيم في الركوع مرة، سبحان ربي الأعلى في السجود مرة، هذا الواجب مرة واحدة، ولكن كونه يكرر ذلك ثلاثاً هذا هو الأفضل والأحسن وهو أدنى الكمال، فإن زاد على ذلك فسبح أربعاً أو خمساً أو ستاً أو سبعاً كان أكمل وأكمل، وقد ثبت عنه ﷺ ما يدل على أنه يعد له عشر في سجوده وركوعه عليه الصلاة والسلام. \nفالحاصل: أن الزيادة على الثلاث لا حرج فيها بل مستحبة؛ لما فيها من مزيد الذكر، ومزيد الطمأنينة في الصلاة، والأفضل للإمام أن يراعي حال المأمومين فلا يطول عليهم تطويلاً يشق عليهم ولا ينقر ولا يعجل، ولكن يكون بين ذلك، والثلاث أدنى الكمال، وإذا زاد عليها فهو أولى حتى يتلاحق الناس في أجزاء الصلاة في ركوعها وسجودها، وحتى يتمكن الثقيل والعاجز من السجود والركوع بسهولة، فالاقتصار على الثلاث فيه تعجيل، والأفضل أن يزيد على الثلاث فيسبح خمساً أو سبعاً حتى يتمكن الناس من الطمأنينة ومتابعة الإمام بسهولة، ويستحب له مع ذلك أن يقول: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، في الركوع والسجود كما فعله النبي عليه الصلاة والسلام، كذلك يستحب له أن يدعو في السجود، كما جاء في السنة عنه عليه الصلاة والسلام أنه قال: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم يعني: فحري أن يستجاب لكم، وقال عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء فالإكثار من الدعاء في السجود أمر مطلوب، وكان النبي ﷺ يدعو في سجوده ويقول: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره، فالدعاء مستحب ومتأكد في السجود من فعل النبي ﷺ وترغيبه وحثه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/4644/حكم-سجود-التلاوة-والزيادة-على-ثلاث-في-تسبيح-الركوع-والسجود ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_019/01909.mp3","categories":["سجود التلاوة والشكر"]},{"id":8030,"question":"هذه الرسالة وردتنا من السودان يقول مرسلها: أنا عوض علي عبيد سوداني، أتقدم لكم بالسؤال التالي عن سورة: اقْرَأْ بِاسْمِ رَبِّكَ [العلق:1] وفي آخر السورة وهي: وَاسْجُدْ وَاقْتَرِبْ [العلق:19]، أيعني بذلك اسْجُدْ وَاقْتَرِبْ [العلق:19] قبل الركوع، وما تفسير هذه الآية، وأرجو التوضيح ولكم مني جزيل الشكر، والله الموفق؟","title":"هل قوله: {وَاسْجُدْ وَاقْتَرِبْ} من سجدات التلاوة؟","answer":"الجواب: هذه السورة شرع الله فيها لنبيه ﷺ السجود والمسلمون كذلك، وهذه من سجدات التلاوة، فالمسلمون يشرع لهم كما شرع لنبيهم ﷺ السجود عند قراءة هذه الآية، فإذا قرأ هذه الآية يسجد، إن كان مفرداً خارج الصلاة، وهكذا إن كان في الصلاة، وإن كان إماماً سجد وسجد معه الناس، وهذه من السجدات التي سجد فيها النبي عليه الصلاة والسلام.\nوقد قال بعض أهل العلم: إن السجدات في المفصل قد نسخت، ولكنه قول ضعيف، والصواب: أنها باقية، وأنها سنة السجدة في النجم، والسجدة في: إِذَا السَّمَاءُ انشَقَّتْ [الانشقاق:1] والسجدة في: اقْرَأْ بِاسْمِ رَبِّكَ [العلق:1] كلها سجدات مشروعة ثابتة عن رسول الله عليه الصلاة والسلام يسجدها الإمام بالمأمومين في الصلاة ويسجدها الإنسان في صلاته في تهجده ونحو ذلك، ويسجدها خارج الصلاة، هذه السنة. نعم.","link":"https://binbaz.org.sa/fatwas/5643/هل-قوله-واسجد-واقترب-من-سجدات-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_079/07903.mp3","categories":["سجود التلاوة والشكر"]},{"id":9723,"question":"سماحة الشيخ يقول هذا السائل: ما هي شروط السجدة عند سماع مقرئ الإذاعة أو آية تتلى بها سجود؟ وهل على الإنسان يجب أن يكون متوضئ أم لا؟","title":"حكم السجود للتلاوة عند سماع آية السجدة من المذياع","answer":"الجواب: السجود للإذاعة لا يشرع لمن سمعه أن يسجد؛ لأنه ليس يقرأ لك، إنما يقرأ لغيره، ..... ..... هو القرآن فقط، السجود للإذاعة ليس فيه سجود إنما تسمع الفائدة فقط، أما إذا قرأ الإنسان يقرأ لك وأنت تستمع له تسجد معه إذا سجد، في المسجد أو في البيت أو في أي مكان تسجد معه إذا سجد، وأنت تستمع له، والنبي ﷺ قرأ عليه زيد بن ثابت سورة النجم فلم يسجد زيد ولم يسجد النبي ﷺ، فدل على أن هذا ليس بواجب والأمر واسع والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/7878/حكم-السجود-للتلاوة-عند-سماع-اية-السجدة-من-المذياع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27214.mp3","categories":["سجود التلاوة والشكر"]},{"id":10199,"question":"يسأل أخونا يقول: هل يجوز للإنسان أن يقرأ القرآن وهو مضطجع على السرير؟ وكيف تنصحونه إذا مر بآية سجود؟","title":"حكم قراءة القرآن وسجود التلاوة للمضطجع","answer":"الجواب: نعم، يقرأ القرآن قائماً وجالساً ومضطجعاً، لا بأس أن يقرأ؛ لقوله جل وعلا: الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِهِمْ [آل عمران:191]، وقوله سبحانه: فَإِذَا قَضَيْتُمُ الصَّلاةَ فَاذْكُرُوا اللَّهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِكُمْ [النساء:103] هذا من نعم الله ومن تيسيره ، والقرآن من أعظم الذكر، فإذا قرأه مضطجع فلا حرج في ذلك، وهو جالس فلا حرج في ذلك، وإذا مرت به السجدة قام وسجد، جلس وسجد إن شاء؛ لأن السجود ليس بواجب سنة مستحب، فإذا قرأ وهو جالس سجد وهو قائم سجد، وهو مضطجع جلس وسجد، لا يسجد وهو مضطجع، يجلس ويسجد. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8369/حكم-قراءة-القران-وسجود-التلاوة-للمضطجع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30910.mp3","categories":["سجود التلاوة والشكر","القرآن وعلومه","قضايا المرأة"]},{"id":10599,"question":"المستمع عيد علي سالم عبدالرحمن من جمهورية مصر العربية الفيوم بعث يسأل عن سجود التلاوة، هل تشترط له الطهارة؟","title":"حكم الطهارة لسجود التلاوة والشكر","answer":"الجواب: سجود التلاوة تشترط له الطهارة عند الأكثرين، عند أكثر أهل العلم، والأرجح أنها لا تشترط؛ لعدم الدليل، وقد كان النبي ﷺ يقرأ القرآن فيمر بالسجدة فيسجد ويسجد معه الناس، ولم يقل لهم: من ليس على طهارة لا يسجد، ومعلوم أن المجالس تضم من هو على وضوء ومن هو على غير وضوء، فلو كانت الطهارة شرطاً لقال لهم: لا يسجد معنا أحد إلا وهو على طهارة، وكان ابن عمر رضي الله عنه يسجد وهو على غير طهارة، وهكذا الشعبي التابعي الجليل، فالصواب أنه لا يشترط، لا بأس أن يسجد وإن كان على غير طهارة، لعدم الدليل، والسجود ليس صلاة لكنه جزء من الصلاة، وهكذا سجود الشكر إذا بشر بنعمة فسجد لله لا يشترط الطهارة في سجود الشكر، كسجود التلاوة سواء أما سجود الصلاة وسجود السهو فهذا لابد من الطهارة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8787/حكم-الطهارة-لسجود-التلاوة-والشكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32614.mp3","categories":["سجود التلاوة والشكر"]},{"id":10657,"question":"هل الطهارة واجبة في سجدة التلاوة وسجدة الشكر؟ وهل هناك سجدة بعد ختم القرآن، حيث أننا بعد أن نختم القرآن نسجد سجدة شكراً لله عز وجل على ختم القرآن والسائل من سوريا؟","title":"هل تشترط الطهارة لسجدتي التلاوة والشكر؟","answer":"الجواب: الصواب أنه لا تشترط الطهارة لسجدة التلاوة والشكر؛ لأن الإنسان قد يتلوه وهو على غير طهارة يسجد، والحمد لله، قد يأتي خبر يسره فيسجد للشكر، والنبي ﷺ كان إذا جاءه أمر يسره سجد لله شكرًا، وكان يقرأ القرآن بين أصحابه فإذا مر بالسجدة سجد وسجدوا معه، ولم يقل لهم: لا يسجد أحد منكم إلا إذا كان على طهارة، معلوم أن المجالس تضم المحدث وغير المحدث، فلو كانت الطهارة شرطًا لقال لهم: الذي ليس على طهارة لا يسجد، فلما سكت دل على أن الطهارة غير شرط.\nأما السجود عند ختم القرآن فلا أصل له، تركه أولى، ترك السجود بعد ختم القرآن أولى لعدم الدليل عليه.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8834/هل-تشترط-الطهارة-لسجدتي-التلاوة-والشكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28519.mp3","categories":["سجود التلاوة والشكر"]},{"id":11621,"question":"هل يجوز للمرأة أن تسجد إذا مرت بآية فيها سجدة وهي في عذرها الشهري، أو من غير وضوء؟","title":"حكم سجود التلاوة للحائض والنفساء","answer":"الجواب:  نعم، سجود التلاوة لا يجب له الوضوء، سجود التلاوة من جنس الذكر، يجوز أن يسجد الإنسان وهو على غير طهارة، هذا هو الصواب، فإذا قرأت الحائض القرآن؛ سجدت للتلاوة، إذا مرت بسجود التلاوة، وهكذا المحدث إذا قرأ وهو على غير طهارة، لكن ليس بجنب، فإنه إذا مر بالسجدة يسجد، أما الجنب لا، لا يقرأ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9804/حكم-سجود-التلاوة-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38815.mp3","categories":["سجود التلاوة والشكر","الحيض والنفاس"]},{"id":11719,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من مكة المكرمة رمزت إلى اسمها بالحروف (أ. م. د) أختنا في أول أسئلتها تقول: ما هي كيفية صلاة الشكر؟","title":"كيفية سجود الشكر وحكم الطهارة له","answer":"الجواب:  ما نعلم صلاة يقال لها: صلاة الشكر، يقال: سجود الشكر، صلاة الشكر ما نعرف شئُا، لكن إذا صلى الإنسان ركعتين في الضحى، أو في الليل، أو في الظهر، وحمد الله، وأثنى عليه، وشكره على نعمه كله طيب، الصلاة مطلوبة كلها خير، في أوقات العبادة، الضحى كله صلاة إلى وقوف الشمس، والظهر كله صلاة إلى بعد صلاة العصر، الليل كله صلاة الحمد لله، إذا صلى الإنسان ركعتين، أو أكثر يشكر الله، ويحمده فيها ويدعوه، ويسأل ربه الخير، كله طيب، لكن ما نعلم في الشرع صلاة يقال لها صلاة الشكر. نعم سجدة يقال لها: سجدة الشكر، مثل الإنسان بشر بأن الله وهبه ولدًا ذكرًا، أو أنثى، فسجد شكرًا على هذه النعمة، أو بشر بأن الله عافى ولده، أو عافى أباه من مرضه، أو أن الذين انقلبت بهم السيارة سلموا، أو تصادموا، بشر بأنهم سلموا، وسجد لله شكرًا، كل هذا طيب، أو جاء فتح إسلامي، إن الله فتح على المسلمين، ونصرهم على عدوهم في حرب بين المسلمين وأعدائهم، فبشر بأن المسلمين انتصروا؛ فسجد لله شكرًا، كما جاء عن الصديق  لما بشر بأن مسيلمة قتل في حرب اليمامة؛ سجد لله شكرًا، وروي عنه ﷺ أنه سجد لله شكرًا لما بلغه قتل الأسود العنسي. فالمقصود: أن السجود لله شكر معروف، وهو مثل سجود الصلاة، سجدة واحدة يسجدها لله، ويشكره على ما حصل من النعمة، يقول......: سبحان ربي الأعلى، سبحان ربي الأعلى، ويحمد ربه، ويشكره، ويدعوه على ما حصل من النعمة التي له، أو للمسلمين. نعم. المقدم: جزاكم الله خيرًا، هل تشترط لها الطهارة سماحة الشيخ؟ الشيخ: لا تشترط، الصواب لا تشترط مثل سجود التلاوة، الصواب لا تشترط الطهارة، والجمهور على أنها شرط، لكن الصواب أنها لا تشترط لعدم الدليل؛ لأنها خضوع لله، خضوع لله، وذكر له  فأشبه التسبيح والتهليل، وأشبه القراءة عن ظهر قلب، لا تشترط لها الطهارة. نعم. المقدم: جزاكم الله خيرًا، سواءً من الحدث الأكبر، أو الأصغر؟ الشيخ: نعم، مطلقًا، نعم، وكان ابن عمر يسجد وهو على غير الطهارة، وكان الشعبي كذلك فيما صح عنهما، نعم، والنبي ﷺ كان يقرأ القرآن في أصحابه في مجالسهم، فإذا سجد؛ سجدوا معه، ولم يقل لهم: من كان على غير طهارة فلا يسجد، ومعلوم أن المجالس تشمل من هو على وضوء، ومن هو على غير وضوء، فلو كانت الطهارة شرطًا، لقال لهم عند السجود: من ليس على طهارة لا يسجد، فلما سجد وسجدوا معه في مجالسهم دل على أن ..... الطهارة ليست شرطًا، إذ لو كانت شرطًا لنبههم -عليه الصلاة والسلام- لأن الله بعثه مبلغًا ومعلمًا، والبيان لا يجوز تأخيره عن وقت الحاجة، واجتماعهم معه في مجالس، وسجودهم معه هو وقت الحاجة للبيان. نعم.","link":"https://binbaz.org.sa/fatwas/9902/كيفية-سجود-الشكر-وحكم-الطهارة-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29908.mp3","categories":["سجود التلاوة والشكر"]},{"id":11751,"question":"ما الذي يجب علينا عمله بالضبط عندما نقابل سجدة في القرآن الكريم؟","title":"حكم سجود التلاوة وما يقال فيه من أدعية","answer":"الجواب:  السنة السجود إذا مررت على السجدة في القرآن، تكبر وتسجد، وتقول: (سبحان ربي الأعلى سبحان ربي الأعلى) مثل سجود الصلاة سواء، تقول فيها مثل السجود في الصلاة (سبحان ربي الأعلى، سبحان ربي الأعلى) تدعو فيها وإذا قلت: (اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره بحوله وقوته، تبارك الله أحسن الخالقين)، فهذا أيضًا سنة، يقال في سجود الصلاة، وفي سجود التلاوة. وهكذا: اللهم اكتب لي بها عندك أجرًا، وامح عني بها وزرًا، واجعلها لي عندك ذخرًا، وتقبلها مني كما تقبلتها من عبدك داود عليه السلام هذا أيضًا لا بأس، ورد في بعض الأحاديث أن النبي ﷺ دعا بذلك، قال: اللهم اكتب لي بها عندك أجرًا، وامح عني بها وزرًا، واجعلها لي عندك ذخرًا، وتقبلها مني كما تقبلتها من عبدك داود -عليه الصلاة والسلام- فهذا لا بأس به. المقصود: أنه يقول في سجوده للتلاوة مثل سجود الصلاة، يقول: (سبحان ربي الأعلى، سبحان ربي الأعلى) (سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي)، (سبوح قدوس رب الملائكة والروح)، (اللهم لك سجدت وبك آمنت ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره بحوله وقوته، تبارك الله أحسن الخالقين) ثم يرفع مكبرًا، إذا كان في الصلاة يرفع مكبرًا، أما خارج الصلاة؛ فيكفي التكبير الأول، وليس فيها تكبير ثانٍ، ولا سلام في خارج الصلاة، أما في الصلاة فيكبر عند السجود، ويكبر عند الرفع، كما فعله النبي -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9933/حكم-سجود-التلاوة-وما-يقال-فيه-من-ادعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39314.mp3","categories":["سجود التلاوة والشكر","سجود السهو","الأدعية والأذكار"]},{"id":11883,"question":"هل يجوز للمرأة الحائض أن تسجد سجود التلاوة؟","title":"حكم سجود التلاوة للحائض والنفساء والجنب","answer":"الجواب:  الصواب أنه لا حرج أن تقرأ وتسجد، هذا هو الصواب، عن ظهر قلب، ما هو من المصحف عن ظهر قلب؛ لأنها ليست مثل الجنب، الجنب مدته قصيرة، يغتسل ويقرأ، لا يقرأ الجنب، ولا يسجد، لكن الحائض والنفساء مدتهما تطول، فالصواب أن لهما أن تقرأا عن ظهر قلب، فإذا مرتا بالسجدة سجدتا؛ لأن السجدة ليست صلاة؛ سجدة التلاوة ليست صلاة، وإنما هي خضوع لله، مثل الذكر لا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10067/حكم-سجود-التلاوة-للحاىض-والنفساء-والجنب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42504.mp3","categories":["سجود التلاوة والشكر","الحيض والنفاس"]},{"id":11884,"question":"أثناء حفظي للقرآن قد أمر بآية فيها سجدة، فهل كلما كررت الآية أكرر السجود، أم يكفي مرة واحدة؟ جزاكم الله خيرًا.","title":"حكم تكرار سجود التلاوة عند تكرار آية السجدة","answer":"الجواب:  هذا الأفضل كلما كررت القراءة يتكرر السجود، هذا الأفضل، وإن اكتفى القاري بالسجدة الأولى؛ فالحمد لله؛ فلا بأس، السجود كله نافلة، سجود التلاوة كله نافلة، لكن إذا كرره يكون أفضل، فإن اكتفى بالسجدة الأولى حين قرأ القراءة الأولى؛ كفى، والحمد لله. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10068/حكم-تكرار-سجود-التلاوة-عند-تكرار-اية-السجدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42505.mp3","categories":["سجود التلاوة والشكر"]},{"id":12049,"question":"هل يجوز أن أسجد للتلاوة في وقت النهي؟","title":"سجود التلاوة وقت النهي","answer":"الجواب:  نعم لا حرج، ليست بصلاة، ثم الصلاة تجوز في وقت النهي إذا كانت من ذوات الأسباب، كصلاة كتحية المسجد، وصلاة الوضوء، وصلاة الطواف إذا طاف الإنسان بعد العصر يصلي تحية المسجد في العصر، يصلي صلاة الطواف في العصر .... لا حرج في هذا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10234/سجود-التلاوة-وقت-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43318.mp3","categories":["سجود التلاوة والشكر"]},{"id":12100,"question":"هل صحيح أن كثرة السجود لله بدعة، علمًا بأنني كثيرًا ما أتذكر نعمة الله علي؛ فأسجد لله شكرًا؟","title":"حكم السجود المفرد دون سبب","answer":"الجواب:  السجود المفرد لا يفعل إلا عند أسبابه، كسجود التلاوة إذا مر على الإنسان آية السجدة يسجد، أو حدث نعمة جديدة؛ فيسجد لله شكرًا، كأن رزقه الله ولدًا، أو يسمع بفتح للمسلمين، ونصر لهم على عدوهم؛ فيسجد لله شكرًا.  أما السجود من دون أسباب فلا أصل له، بدعة، يصلي صلاة كاملة، يصلي ركعتين، أو أكثر، ويسلم من كل ثنتين، هذا مشروع طيب، الصلاة كلها خير، لكن مثنى مثنى، سواءً في الليل أو في النهار.  أما السجود المفرد فإنه لا يفعله إلا لأسباب مثل: للتلاوة إذا مر بآية السجدة؛ سجد، أو للشكر مثل إذا رزقه الله نعمة جديدة من ولد، أو فتح للمسلمين، أو عافية من حادث، أو ما أشبه ذلك، يسجد لله شكرًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10285/حكم-السجود-المفرد-دون-سبب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43703.mp3","categories":["سجود التلاوة والشكر"]},{"id":12404,"question":"يقول: حدثونا عن سجود التلاوة، وهل تشترط له الطهارة والقبلة؟","title":"حكم الطهارة واستقبال القبلة لسجود التلاوة","answer":"الجواب:  سجود التلاوة سنة، قربة، كان النبي ﷺ إذا مر بالسجدة؛ سجد -عليه الصلاة والسلام- وليس صلاة، فلا يشترط لها الطهارة ولا قبلة، ولكن أفضل كونه يسجد إلى القبلة، وكونه على طهارة فأفضل، ولهذا ذهب الأكثرون إلى أنه لابد من طهارة، ولابد من القبلة، لكن الصحيح أنه لا يلزم، فهو خضوع لله من جنس الذكر من جنس سبحان الله، والحمد لله، والله أكبر. فالإنسان يذكر الله إلى جهة القبلة، وإلى غيرها، ويخضع له  بذكره لله، وبدعائه، ولا يشترط له القبلة ولا الطهارة، لكن لو تطهر، وسجد إلى القبلة؛ كان هذا أكمل وأفضل، وفيه خروج من خلاف العلماء، وقد ثبت عنه ﷺ أنه كان يقرأ بين أصحابه، فإذا مر بالسجدة؛ سجد، وسجدوا معه، ولم يقل لهم: من ليس على طهارة لا يسجد، والمجالس تجمع من هو على طهارة، ومن هو على غير طهارة. فلو كانت الطهارة شرطًا لنبههم -عليه الصلاة والسلام- والأصل عدم شرط الطهارة، هذا هو الأصل؛ ولأنها ليست صلاة سجود، مجرد سجود، الطهارة إنما تجب للصلاة؛ لقوله ﷺ: مفتاح الصلاة الطهور وهذه ليست صلاة، ولكنها جزء من صلاة. وهكذا القراءة عن ظهر قلب ليست صلاة، فلا يشترط لها الطهارة، وهكذا سبحان الله، والحمد لله، وسائر الذكر لا يشترط لها الطهارة، فسجود التلاوة من جنس ذلك. وهكذا سجود الشكر من جنسه، لو بشر بولد، أو بفتح للمسلمين، ونصر لهم على عدوهم، وسجد شكرًا لله؛ فلا حرج عليه، وهو مأجور، ولو كان على غير طهارة، لكن الأفضل أن يكون إلى القبلة؛ خروجًا من الخلاف، ولأن القبلة أولى من غيرها، فيسجد إلى القبلة، ويتحرى ما هو الأكمل والأفضل وإلا فليس بشرط. نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/10609/حكم-الطهارة-واستقبال-القبلة-لسجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45509.mp3","categories":["سجود التلاوة والشكر"]},{"id":12411,"question":"يسأل عن الأذكار التي يقولها المسلم في سجود السهو؟","title":"ما الأذكار المشروعة في سجود السهو؟","answer":"الجواب:  سجود السهو مثل سجود الصلاة، يذكر فيه ما يقول في سجود الصلاة: (سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم، ربنا وبحمدك، اللهم اغفر لي، سبوح قدوس رب الملائكة والروح، اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه، وصوره، وشق سمعه وبصره، بحوله وقوته، تبارك الله أحسن الخالقين) كل هذا يقال في سجود الصلاة، يقوله في سجود التلاوة، وفي سجود السهو، سواء سواء، سجود الصلاة، سجود التلاوة، سجود السهو، سجود الشكر، كلها يقال فيها هذا الذكر: (سبحان ربي الأعلى، سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، سبوح قدوس رب الملائكة والروح، سبحان ذي الجبروت والملكوت والكبريا والعظمة، اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره، بحوله وقوته، تبارك الله أحسن الخالقين).  ويدعو في السجود أيضًا، يدعو بما تيسر من الدعاء؛ لقول النبي ﷺ: أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء. وقوله ﷺ: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10618/ما-الاذكار-المشروعة-في-سجود-السهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40206.mp3","categories":["سجود التلاوة والشكر","سجود السهو","الأدعية والأذكار"]},{"id":12726,"question":"المستمع أحمد إبراهيم الخالدي من شقرا بعث برسالة يقول فيها: نرى كثيرًا من الشباب الذين درسوا ونجحوا حينما يقرؤون القرآن الكريم، ويمرون بالآيات التي فيها سجدة، يمرون بالسجدة دون أن يسجدوا، وإذا سألتهم عن ذلك يقولون: إننا لم ندرس دعاء السجدة أثناء دراستنا، ولا نعرفها، نرجو أن تتفضلوا سماحة الشيخ بتوجيه الناس حول الدعاء الذي يقال في سجود التلاوة؟ جزاكم الله خيرًا.","title":"حكم سجود التلاوة وما يقال فيه من دعاء","answer":"الجواب:  سجود التلاوة مثل سجود الصلاة، يقال فيه ما يقال في سجود الصلاة، والسنة إذا مر القارئ بآية السجدة أن يسجد ويقول: سبحان ربي الأعلى، سبحان ربي الأعلى ويكفي، مثل سجود الصلاة سواء، وإذا قال زيادة: اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره، بحوله وقوته، تبارك الله أحسن الخالقين فهذا أفضل وهذا يقال في سجود الصلاة أيضًا، هذا يقال في سجود الصلاة أيضًا، مثل سجود التلاوة سواءً سواء. فالمقصود: أنه ليس بعذر، لكن السجود ليس بواجب، هو سنة، سجود التلاوة سنة ونافلة، لكن المشروع للمؤمن إذا مر بآية سجدة أن يسجد، ولو كان على غير طهارة، يجوز أن يسجد على غير طهارة على الصحيح، ويقول في سجوده مثلما يقول في سجود الصلاة، سبحان ربي الأعلى، سبحان ربي الأعلى، اللهم اغفر لي، اللهم أنجني من النار، مثلما يقول في سجود الصلاة سواءً بسواء، ويقال في سجود الصلاة وفي سجود التلاوة: اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره، بحوله وقوته، تبارك الله أحسن الخالقين يقال في هذا وهذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10939/حكم-سجود-التلاوة-وما-يقال-فيه-من-دعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46014.mp3","categories":["سجود التلاوة والشكر","الأدعية والأذكار"]},{"id":13400,"question":"هل سجود التلاوة فيه تسليمتان، أم تسليمة واحدة على اليمين؟","title":"كم تسليمة لسجود التلاوة؟","answer":"الجواب: إذا كان خارج الصلاة ليس فيه تسليم، ولا تكبير إلا التكبيرة الأولى فقط عند السجود، يكبر فقط، هذا هو السنة إذا كان خارج الصلاة، ويقول في سجوده: سبحان ربي الأعلى، سبحان ربي الأعلى اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه، وصوره، وشق سمعه وبصره بحوله وقوته، تبارك الله أحسن الخالقين مثل سجود الصلاة، ويدعو فيه مثلما يدعو في سجود الصلاة، لكن ليس فيه تكبير إلا التكبيرة الأولى عند السجود، هذا هو المشروع. أما إذا كان في داخل الصلاة؛ فإنه يكبر عند الهوي، ويكبر عند الرفع؛ لأنه ﷺ كان إذا قام كبر، وإذا سجد كبر، وكان يكبر في كل خفض ورفع في الصلاة، فسجود التلاوة في الصلاة مثل سجود الصلاة، يكبر في الخفض، ويكبر في الرفع، إذا كان في داخل الصلاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11693/كم-تسليمة-لسجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47706.mp3","categories":["سجود التلاوة والشكر"]},{"id":13597,"question":"آخر سؤال له يقول فيه: حضرت يومًا ختمة القرآن الكريم في أحد المساجد، وعندما جاء دوري؛ قرأت سورة الانشقاق، وعند الآية رقم واحد وعشرين، وعند موضع السجود أردت أن أسجد، ولكن الإمام أشار لي بعدم السجود، وهم أيضًا لم يسجدوا، فما هو حكم السجود في مثل الحال التي ذكرت؟ جزاكم الله خيرًا.","title":"حكم سجود التلاوة في الصلاة وخارجها","answer":"الجواب: السنة السجود إذا قرأ الإنسان آية السجدة، سواءً كان في الصلاة، أو في خارجها، لكن المأموم لا يسجد، إنما الإمام هو الذي يسجد، فإذا سجد الإمام؛ تبعوه، وإلا فلا، وأما إذا كان يصلي وحده في النافلة، أو في الفريضة؛ لأنه ما أدرك الفريضة، أو معذور مريض، لا يحضر. فإذا قرأ السجدة؛ يسجد، هذه السنة، سواء كان هذا في (إذا السماء انشقت) أو في غيرها، وهكذا إن كان يقرأ قراءة خارج الصلاة في بيته، أو في المسجد، إذا مر بآية السجدة؛ سجد، هذا هو السنة، وليست واجبة، ولكنها سنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11928/حكم-سجود-التلاوة-في-الصلاة-وخارجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48009.mp3","categories":["سجود التلاوة والشكر"]},{"id":13817,"question":"يقول: أرجو من سماحة الشيخ أن يحدثنا عن سجود التلاوة وسجود السهو، ما هو الدعاء الذي يقال في كلا السجودين؟ جزاكم الله خيرًا.","title":"ما الذكر الذي يقال في سجودي التلاوة والشكر؟","answer":"الجواب: سجود التلاوة وسجود الشكر يقال فيهما ما يقال في سجود الصلاة، وهكذا سجود التلاوة وهكذا سجود الصلاة كذلك يقال فيها: سبحان ربي الأعلى، سبحان ربي الأعلى ، اللهم اغفر لي، يدعو فيهما كما يدعو في سجود الصلاة يدعو في سجود السهو وفي سجود الشكر سجود التلاوة؛ لأن الحكم واحد، الله جل وعلا قال: فَاسْجُدُوا لِلَّهِ وَاعْبُدُوا[النجم:62]، والنبي ﷺ كان يدعو في سجوده ويقول عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء، ويقول عليه الصلاة والسلام: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم، وهذا يعم جميع أنواع السجود، وكان يقول في سجوده: سبحان ربي الأعلى، سبحان ربي الأعلى، ويقول أيضًا في السجود والركوع: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، ويقول فيهما: سبوح قدوس، رب الملائكة والروح، فالمشروع في سجود التلاوة وسجود الشكر مثل المشروع في سجود الصلاة. نعم.","link":"https://binbaz.org.sa/fatwas/12185/ما-الذكر-الذي-يقال-في-سجودي-التلاوة-والشكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53703.mp3","categories":["سجود التلاوة والشكر","الأدعية والأذكار"]},{"id":13818,"question":"سماحة الشيخ هل يسجد الشخص وهو غير متوضئ؟","title":"هل يجوز السجود على غير طهارة؟","answer":"الجواب: في سجود التلاوة والشكر نعم.  أما سجود الصلاة، جزء من الصلاة لا بد من الطهارة. أما سجود التلاوة فسجود مستقل، إذا كان خارج الصلاة جاز أن يسجد على غير طهارة على الصحيح، وهكذا سجود الشكر؛ لأنهما يحدثان بأسباب قد تقع والإنسان على غير طهارة، قد تأتيه النعمة يبشر بها وهو على غير طهارة قد يقرأ القرآن وهو على غير طهارة من غير المصحف، فإذا مر بآية السجود أو جاءه ما يبشره بخير وسجد لله شكرًا كل هذا طيب، في الحديث: كان النبي ﷺ إذا جاءه أمر يسره خر ساجدًا لله، ولما جاء للصديق خبر قتل مسيلمة خر ساجدًا لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12186/هل-يجوز-السجود-على-غير-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53704.mp3","categories":["سجود التلاوة والشكر"]},{"id":13975,"question":"المستمعة أم أحمد من المنطقة الشمالية رفحا، وتعمل معلمة، بعثت برسالة ضمنتها ثمانية أسئلة.في سؤالها الأول تقول: هل تغطية الرأس واليدين والقدمين واجبة عند سجود التلاوة؟","title":"حكم تغطية المرأة رأسها ويديها وقدميها لسجود التلاوة","answer":"الجواب: ليست واجبة لا، سجود التلاوة ليست صلاة، بل هي خضوع لله وذل بين يديه، كالقراءة والذكر ونحو ذلك، هذا هو الصواب، وقال بعض أهل العلم: إنها كالصلاة، لا بد من طهارة ولا بد من ستر عورة، فإذا سجدت المرأة بتستر؛ كان هذا أفضل وأولى خروجًا من خلاف العلماء، وهكذا إذا كانت على طهارة، كالرجل سواء، ولكن لا يجب هذا، لو سجدت ورأسها مكشوف، أو وهي على غير وضوء؛ فالسجود صحيح على الصحيح، ولا حرج في ذلك، كالرجل، فإن سجود التلاوة يمر على الإنسان وهو يقرأ القرآن عن ظهر قلب وهو على غير طهارة.\nولم يثبت عن النبي ﷺ أنه أمر بذلك، وقد ثبت عن ابن عمر  ما يدل على أنه ليس بشرط، وأنه لا مانع من السجود على غير طهارة.\nفالحاصل: أن سجود التلاوة وسجود الشكر لا يشترط لهما الطهارة، فلو بشر بولد له أو بفتح إسلامي، أو بأمر يسر ينفع المسلمين؛ فسجد شكراً لله، فلا بأس ولو كان على غير طهارة، ولما بلغ الصديق  مقتل مسيلمة الكذاب سجد لله شكرا.\nفالحاصل: أن سجود التلاوة وسجود الشكر لا يشترط لهما الطهارة، ولا السترة التي تشترط في الصلاة، بل الأمر فيهما أوسع والحمد لله، هذا هو الصواب.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12420/حكم-تغطية-المراة-راسها-ويديها-وقدميها-لسجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60608.mp3","categories":["سجود التلاوة والشكر","ستر العورة للمصلي","قضايا المرأة"]},{"id":14034,"question":"يسأل أخونا أيضًا عن عدد السجدات في القرآن الكريم، مع توضيح السجدات الحتمية منها؟","title":"عدد السجدات في القرآن الكريم وهل بعضها واجبة؟","answer":"الجواب: سجدات التلاوة كلها سنة، ما فيها حتمية، كلها سنة ليست واجبة، وهي خمسة عشر سجدة على الصحيح: منها سجدة آخر الأعراف، ومنها سجدة سورة الرعد، ومنها سجدتان في الحج، وسجدة في سورة مريم، وسجدة في بني إسرائيل سبحان، وسجدة في الفرقان، وسجدة في ألم تنزيل السجدة، وسجدة في سورة ص، وسجدة في النجم في آخرها، وسجدة في إذا السماء انشقت، وسجدة في اقرأ باسم ربك.\nهي خمسة عشر سجدة، سنة كلها، إذا سجد فهو أفضل وهو السنة، وإن لم يسجد فلا إثم عليه، وقد قرأ النبي ﷺ سورة النجم في بعض الأحيان فلم يسجد؛ فدل على أنها لا تجب، قال عمر : \"إن الله لم يوجب السجود إلا أن نشاء\"، فالمعنى أن من سجد فله أجر ومن لم يسجد فلا حرج عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12469/عدد-السجدات-في-القران-الكريم-وهل-بعضها-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60709.mp3","categories":["سجود التلاوة والشكر"]},{"id":14407,"question":"يقول: إذا صليت بالناس صلاة الفريضة، وقرأت بعد سورة الفاتحة سورة أخرى فيها سجدة، كسورة النجم، أو سورة العلق مثلًا، فماذا أفعل أأركع أم أسجد؟أفيدوني بذلك.","title":"ماذا يفعل الإمام إذا مر بآية فيها سجدة؟","answer":"الجواب: إذا كانت الصلاة جهرية كالعشاء والفجر والجمعة تسجد إذا مررت بآية سجدة كآخر النجم، وآخر العلق تسجد، النبي كان يسجد -عليه الصلاة والسلام-، تكبر وتسجد ويسجد الناس، أما إذا كانت سرية قرأتها في الظهر، أو في العصر فلا تسجد؛ لأنه يشوش على الناس، لا يدرون ما الذي أوجب لك ذلك؟ قد يظنون أنك ساهٍ. فالمقصود: في السرية لا تسجد إذا قرأت سجدة، أما في الجهرية تسجد، نعم.","link":"https://binbaz.org.sa/fatwas/12889/ماذا-يفعل-الامام-اذا-مر-باية-فيها-سجدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55304.mp3","categories":["سجود التلاوة والشكر"]},{"id":14418,"question":"يقول: عند سماعي آية فيها سجدة هل يجوز عند سماعها أن أسجد وأنا على غير وضوء وما هو الدعاء الوارد عن الرسول ﷺ في ذلك؟","title":"حكم سجود التلاوة بغير طهارة وماذا يقال فيه؟","answer":"الجواب: إذا قرأ الإنسان السجدة يسجد، ولو كان على غير طهارة على الصحيح، مثل سجود الشكر، لا تلزم له الطهارة؛ لعدم الدليل، وهكذا لو سمعها كان يستمع لقارئ، ثم سجد القارئ يسجد معه إذا سجد القارئ يسجد معه، إذا كان يستمع له، ولو كان على غير طهارة. ويقول في السجود مثل سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحان ربي الأعلى، اللهم لك سجدت، إلى آخره، مثل سجود الصلاة، الإنسان يدعو فيها مثل ما يدعو في سجود الصلاة الحكم واحد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12900/حكم-سجود-التلاوة-بغير-طهارة-وماذا-يقال-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55314.mp3","categories":["سجود التلاوة والشكر"]},{"id":14635,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول في نهاية رسالته المرسل: المرضي حسب الله محمد، سوداني مقيم في الكويت، أخونا يقول في رسالته: عند قراءتي للقرآن تمر بي بعض الآيات بها سجدة، هل يشترط استقبال القبلة فيها؟ هذا هو سؤاله الأول حول هذا الموضوع شيخ عبدالعزيز.","title":"حكم استقبال القبلة في سجود التلاوة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فسجود التلاوة سنة وقربة وطاعة، فعله المصطفى -عليه الصلاة والسلام-، ولكن ليس له حكم الصلاة في أصح قولي العلماء، والأفضل أن يسجد إلى القبلة، وأن يكون على طهارة إذا تيسر ذلك، لكن لو سجد إلى غير القبلة، أو على غير طهارة أجزأ ذلك على الصحيح. أما الجمهور من أهل العلم فيقولون: إنه لا بد من استقبال القبلة إلحاقًا له بالصلاة، والأظهر في الدليل أنه يلحق بالذكر لا بالصلاة، فهو من جنس الذكر، كما يذكر الله الإنسان قائمًا وقاعدًا، وإلى القبلة وغيرها، فهكذا السجود، يسجد إلى القبلة وإلى غيرها، لكن الأفضل والأولى أن يكون سجوده إلى القبلة؛ لأن هذا هو الأفضل، وفيه خروج من خلاف العلماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13128/حكم-استقبال-القبلة-في-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62701.mp3","categories":["سجود التلاوة والشكر"]},{"id":14637,"question":"سؤاله الثاني حول هذا الموضوع: ماذا يقال في هذه السجدة؟","title":"ماذا يقال في سجود التلاوة؟","answer":"الجواب: يقول مثلما يقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره، بحوله وقوته، تبارك الله أحسن الخالقين مثل سجود الصلاة سواء، فإن هذا يقال في سجود الصلاة، وإذا دعا بذلك فكذلك الدعاء مشروع؛ لقول النبي ﷺ: أما السجود فأكثروا فيه من الدعاء وقال -عليه الصلاة والسلام-: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء. فالدعاء مشروع في السجود في الصلاة النافلة والفريضة، وهكذا سجود التلاوة، وسجود الشكر، يشرع فيها مثلما يشرع في سجود الصلاة، نعم.\nالمقدم: جزاكم الله خيرًا. المقدم: هل بعدها سلام؟\nالشيخ: ليس لها سلام على الصحيح، إنما يكبر في أول السجود فقط، وليس لها تكبير ثانٍ، وليس لها سلام، هذا هو الصحيح، لكن إذا كان في الصلاة سجد للصلاة يكبر عند السجود وعند الرفع إذا كان في الصلاة؛ لأنه -عليه الصلاة والسلام- كان إذا كان في الصلاة يكبر في كل خفض ورفع -عليه الصلاة والسلام-.  أما في خارج الصلاة فإنه يكبر عند السجود فقط، ويكفي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13129/ماذا-يقال-في-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62702.mp3","categories":["سجود التلاوة والشكر","الأدعية والأذكار"]},{"id":15509,"question":"تقول هذه السائلة أم عبدالرحمن: في صلاة التراويح والتهجد نكون في المسجد، ويكون فيه سجدة تلاوة فماذا نفعل؟ هل نكمل مع الإمام أم نسجد؟","title":"ما يعمل من أخطأ فركع عند سجود الإمام للتلاوة؟","answer":"الجواب: نعم، عليكم أن تكملوا مع الإمام، وهذا الركوع لا يضركم للجهل؛ لأنكم جاهلون بالأمر، فإذا سمعتموه رفع من السجدة، أو علمتم أنه قام إلى القراءة، فقوموا من الركوع، واستمروا معه، وهذا الركوع لا يضر صلاتكم؛ لأنه عن غلط منكم، ولم تتعمدوا مخالفة أمر الله، بل ظننتم أنه راكع فركعتم.  فالحاصل: أن هذا الركوع الذي فعلتموه لا يضركم، وإذا رفع الإمام وسمعتموه يقرأ فارفعوا، واستمروا معه. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14048/ما-يعمل-من-اخطا-فركع-عند-سجود-الامام-للتلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56912.mp3","categories":["سجود التلاوة والشكر","صلاة الجماعة"]},{"id":15512,"question":"هذا السائل يوسف سالم يقول: كنت أستمع إلى إذاعة القرآن الكريم، ومر القارئ بآية يوجد فيها سجدة، هل نؤمر بالسجود ونحن نستمع إلى القرآن؟","title":"حكم سجود التلاوة لمن يستمع للقرآن من الإذاعة","answer":"الجواب: إذا سجد فاسجدوا، وأما إذا ما سجد فليس عليكم سجود، أما إذا سجد وأنتم تستمعون له فاسجدوا، نعم.","link":"https://binbaz.org.sa/fatwas/14050/حكم-سجود-التلاوة-لمن-يستمع-للقران-من-الاذاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56914.mp3","categories":["سجود التلاوة والشكر"]},{"id":15704,"question":"هذا سائل يقول في هذا  هل يجوز لسجدة التلاوة حين يسمعها الإنسان وهو ليس متوضئ، وهل بها سلام يا سماحة الشيخ؟","title":"حكم الطهارة والتسليم في سجود التلاوة","answer":"الجواب: إذا استمع للقاري، سجد معه، ولو كان بغير وضوء، الطهارة لا تشترط لسجود التلاوة، إذا كان خارج الصلاة، وقرأ ومر بالسجدة يسجد، ولو كان على غير طهارة، والذي يستمع له يستحب له السجود معه.  وليس لها سلام، لكن يكبر في أولها: الله أكبر، ويسجد، وليس لها تكبير ثانٍ ولا سلام، إذا كانت خارج الصلاة.\nأما إذا كان في الصلاة، فإنه يكبر عند السجود، ويكبر عند الرفع، كسجدات الصلاة. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14262/حكم-الطهارة-والتسليم-في-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57313.mp3","categories":["سجود التلاوة والشكر"]},{"id":15765,"question":"إذا كنت أقرأ القرآن بعد صلاة الصبح، ثم وصلت إلى موضع سجود، هل أسجد رغم أن الوقت وقت نهي، أم لا؟","title":"حكم سجود التلاوة في أوقات النهي","answer":"الجواب: نعم، سجود التلاوة ليس له وقت نهي، ليس بصلاة، إذا قرأت بعد العصر أو بعد الفجر فاسجد؛ لأنه خشوع لله وذل وانكسار ليس صلاة، هذا هو الصواب، فإذا قرأ الإنسان سجدة من آيات السجود سجد بعد العصر، أو بعد الفجر، ثم أيضًا هي من ذوات الأسباب، لو كانت صلاة هي من ذوات الأسباب، سببها أنك قرأت الآية التي فيها السجدة فتسجد، هذا هو السنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14353/حكم-سجود-التلاوة-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70712.mp3","categories":["سجود التلاوة والشكر"]},{"id":15953,"question":"من القصيم رسالة بعثت بها إحدى الأخوات المستمعات تقول: أم فهد، أم فهد تسأل عن سجود الشكر كيف يكون؟ وما هي مشروعيته؟جزاكم الله خيرًا.","title":"كيفية سجود الشكر","answer":"الجواب: سجود الشكر مثل سجود الصلاة سجدة واحدة، يقول فيها ما يقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، يحمد الله، ويثني عليه على النعمة التي حصلت، يدعوه -جل وعلا- ويشكره، هذا سجود الشكر كون الإنسان بشر بأن الله -جل وعلا- رزقه ولدًا، أو بشر بأن أمه شفيت من مرضها أو أباه، أو بشر بأن المسلمين فتح الله عليهم، ونصروا على عدوهم، فإنه يشرع له السجود شكرًا لله، ولو كان على غير طهارة، ويقول في السجود مثلما يقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، ويقول: اللهم اغفر لي، اللهم ارزقني الشكر على نعمتك، الحمد لله على هذه النعمة، ونحو ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14560/كيفية-سجود-الشكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74610.mp3","categories":["سجود التلاوة والشكر"]},{"id":16306,"question":"الأخت المستمعة فاطمة موسى من فيفا بعثت برسالة وضمنتها عددًا من الأسئلة في أحدها تقول: إذا كنت أقرأ القرآن الكريم، وفي أثناء ذلك وجدت علامة سجدة، فماذا أفعل، وماذا أقول؟","title":"ما يفعل من مر بآية سجدة أثناء تلاوة القرآن؟","answer":"الجواب: السنة للقارئ -سواء كان القارئ رجلًا أو امرأة- إذا مر على آية السجدة، وانتهى منها؛ قرأها، يكبر، ويسجد، إن كان في الصلاة يسجد وهو في الصلاة فرضًا كان أو نفلًا، يكبر ويسجد ويقول مثلما يقول في سجود الصلاة: (سبحان ربي الأعلى، سبحان ربي الأعلى) سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي. ويدعو ربه بما تيسر من الدعاء، مثل: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره كان يدعو به النبي ﷺ بهذا الدعاء في سجوده، مثل: اللهم إنك عفو، تحب العفو؛ فاعف عني اللهم اغفر لي ولوالدي -إذا كان والداه مسلمين- اللهم اغفر لي ولوالدي ولجميع المسلمين، اللهم أصلح قلبي وعملي، اللهم اهدني سواء السبيل، وما أشبهه من الدعوات الطيبة، ثم يرفع مكبرًا إن كان في الصلاة، مثل سجود الصلاة يرفع مكبرًا، ويعود إلى قراءته إذا كان في الصلاة.  أما إذا كان خارج الصلاة يكبر فقط عند السجود، وليس هناك تكبير عند الرفع، ولا تسليم، إذا كان في خارج الصلاة، لم يرد إلا التكبير عند السجود فقط، إذا كان في خارج الصلاة، يرفع ويقرأ إن شاء، أو يقوم إن شاء، ما في تكبير، ولا في سلام، هذا هو الصواب في سجود التلاوة إذا كان خارج الصلاة. أما إذا كان في داخل الصلاة؛ فإنه يكبر عند السجود، ويكبر عند الرفع حسب الأدلة الشرعية، نعم. المقدم: جزاكم الله خيرًا، وهذا في حق الرجال والنساء سواء؟ الشيخ: في حق الرجال والنساء جميعًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15006/ما-يفعل-من-مر-باية-سجدة-اثناء-تلاوة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81007.mp3","categories":["سجود التلاوة والشكر"]},{"id":16313,"question":"الأخت المستمعة فاطمة موسى من فيفا بعثت برسالة وضمنتها عددًا من الأسئلة في أحدها تقول: إذا كنت أقرأ القرآن الكريم، وفي أثناء ذلك وجدت علامة سجدة، فماذا أفعل، وماذا أقول؟","title":"ما يفعل من مر بآية سجدة أثناء تلاوة القرآن؟","answer":"الجواب: السنة للقارئ -سواء كان القارئ رجلًا أو امرأة- إذا مر على آية السجدة، وانتهى منها؛ قرأها، يكبر، ويسجد، إن كان في الصلاة يسجد وهو في الصلاة فرضًا كان أو نفلًا، يكبر ويسجد ويقول مثلما يقول في سجود الصلاة: (سبحان ربي الأعلى، سبحان ربي الأعلى) سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي. ويدعو ربه بما تيسر من الدعاء، مثل: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره كان يدعو به النبي ﷺ بهذا الدعاء في سجوده، مثل: اللهم إنك عفو، تحب العفو؛ فاعف عني اللهم اغفر لي ولوالدي -إذا كان والداه مسلمين- اللهم اغفر لي ولوالدي ولجميع المسلمين، اللهم أصلح قلبي وعملي، اللهم اهدني سواء السبيل، وما أشبهه من الدعوات الطيبة، ثم يرفع مكبرًا إن كان في الصلاة، مثل سجود الصلاة يرفع مكبرًا، ويعود إلى قراءته إذا كان في الصلاة.  أما إذا كان خارج الصلاة يكبر فقط عند السجود، وليس هناك تكبير عند الرفع، ولا تسليم، إذا كان في خارج الصلاة، لم يرد إلا التكبير عند السجود فقط، إذا كان في خارج الصلاة، يرفع ويقرأ إن شاء، أو يقوم إن شاء، ما في تكبير، ولا في سلام، هذا هو الصواب في سجود التلاوة إذا كان خارج الصلاة. أما إذا كان في داخل الصلاة؛ فإنه يكبر عند السجود، ويكبر عند الرفع حسب الأدلة الشرعية، نعم. المقدم: جزاكم الله خيرًا، وهذا في حق الرجال والنساء سواء؟ الشيخ: في حق الرجال والنساء جميعًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15006/ما-يفعل-من-مر-باية-سجدة-اثناء-تلاوة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81007.mp3","categories":["سجود التلاوة والشكر"]},{"id":16475,"question":"تسأل وتقول: ما هي صفة سجود الشكر؟ جزاكم الله خيرًا.","title":"ما صفة سجود الشكر؟","answer":"الجواب: سجود الشكر مثل سجود الصلاة، ومثل سجود السهو، ومثل سجود التلاوة سجدة واحدة، يقول فيها: سبحان ربي الأعلى، سبحان ربي الأعلى، يحمد الله، ويثني عليه، ويشكره على ما منَّ به عليه من صحة، أو ولد، أو نصر للإسلام، وفتح على المسلمين، أو نحو ذلك مما يسره، أو يسر المسلمين، النبي ﷺ سجد للشكر، وهكذا الصديق  لما جاءه فتح اليمامة، ومقتل مسيلمة الكذاب؛ سجد لله شكرًا. والصحيح: أنه يجوز ولو كان الساجد على غير طهارة، إذا جاءه الخبر السار؛ سجد، وإن كان على غير طهارة. وهكذا سجود التلاوة، من جنس سجود الشكر سجدة واحدة عند تلاوة الآيات التي فيها السجود، ولو كان على غير طهارة في أصح قولي العلماء. يقول فيه مثل ما يقول في سجود الصلاة، سجود التلاوة، وسجود الشكر، وسجود السهو كله يقال فيه ما يقال في سجود الصلاة: (سبحان ربي الأعلى، سبحان ربي الأعلى.. سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي... سبوح قدوس رب الملائكة والروح) ويدعو فيه بما يسر الله من الدعوات الطيبة، ويشكر الله في سجود الشكر زيادة، يشكر الله على النعمة التي بلغته. ويقول في السجود أيضًا: اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه، وصوره، وشق سمعه، وبصره بحوله وقوته، تبارك الله أحسن الخالقين يقال هذا في سجود الصلاة، سجود التلاوة، سجود الشكر، مع: سبحان ربي الأعلى لا بد من سبحان ربي الأعلى لابد من كلمة سبحان ربي الأعلى ولو مرة، وإذا كررها ثلاثًا، أو خمسًا كان أفضل، وأولى في جميع أنواع السجود، سجود التلاوة... سجود الشكر... سجود الصلاة... سجود السهو، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15189/ما-صفة-سجود-الشكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75603.mp3","categories":["سجود التلاوة والشكر"]},{"id":16580,"question":"أخونا له سؤال يسأل فيقول: ما حكم سجدة التلاوة؟ هل المسلم يسجد حتى لو كان يعمل وهو يسمع القرآن في أثناء الصلاة عن السجدة في الصلاة الجهرية، وأنا أؤم المصلين؟ ثم أسألكم عن الطريقة الصحيحة لسجدة التلاوة، وكيف أطبقها على الوجه الصحيح؟ جزاكم الله خيرًا.","title":"أحكام سجود التلاوة","answer":"الجواب: سجود التلاوة سنة، وهي سجدات معلومة في القرآن، خمس عشرة سجدة في القرآن، أولها في آخر الأعراف، وآخرها في سورة (اقرأ) في آخرها، إذا مر بها المؤمن في خارج الصلاة سجد، ولو كان على غير طهارة على الصحيح، لا يشترط لها الطهارة، والأفضل أن يكبر تكبيرة في أولها فقط، ثم يسجد ويقول في السجود مثل ما يقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، يدعو بما تيسر، وليس فيها تسليم، ولا تكبير ثان، هذا هو المختار، هذا هو الأرجح. وإن كان في الصلاة، مر بها في الصلاة، شرع له السجود، الصلاة الجهرية: كالمغرب، والعشاء، والفجر، والجمعة، شرع له السجود، والمأمومون يسجدون خلفه، إذا كان إمامًا يسجدون معه إذا سجد، أما في السرية -وهو إمام- فلا يشرع له السجود؛ لأنه قد يشوش على الناس، في السرية إذا قرأها في القراءة السرية: كالظهر والعصر، والثالثة من المغرب، والثالثة والرابعة من العشاء، فالأفضل ألا يسجد؛ لئلا يشوش على الناس، إلا إذا كان يصلي وحده؛ فلا بأس، كالذي يصلي نافلة، أو فاتته الصلاة الفريضة، ويصلي وحده، لا بأس أن يسجد في السرية؛ لعدم التشويش.  وفي الصلاة يكبر في كل خفض ورفع، إذا سجد يكبر، وإذا رفع يكبر؛ لأن النبي ﷺ كان يكبر في كل خفض ورفع، يدخل في ذلك سجود التلاوة في الصلاة، وهي سنة غير واجبة؛ لأنه ثبت عنه ﷺ في الصحيحين أنه قرأ عليه زيد بن ثابت  سورة النجم، فلم يسجد فيها -عليه الصلاة والسلام- فدل ذلك على عدم الوجوب، وقال عمر  عمر بن الخطاب : «إن الله لم يفرض السجود إلا أن نشاء» يعني: فمن شاء سجد، ومن شاء لم يسجد، فهي سنة غير واجبة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15300/احكام-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75802.mp3","categories":["سجود التلاوة والشكر"]},{"id":16630,"question":"نختتم هذه الحلقة برسالة وصلت إلى البرنامج من السودان، باعثها مستمع يقول قابل قبل الحربي يقول: هل هناك تكبيرة وتسليمة في سجدة التلاوة؟","title":"ما حكم التكبير والتسليم في سجود التلاوة؟","answer":"الجواب: الأفضل تكبيرة عند السجود إذا كان خارج الصلاة عندما يريد السجود يكبر يقول: الله أكبر، ويسجد للتلاوة، ولا يشترط الطهارة، ولا السلام، ولا تكبير ثان، ما يشترط تكبير ثان، ولا سلام؛ لأنه لم يرد في الأحاديث الصحيحة، ولكن إذا كان على طهارة تكون أفضل، وليست الطهارة شرطًا، قد ثبت عن ابن عمر -رضي الله عنهما- أنه كان يسجدها على غير وضوء، وهكذا جاء عن الشعبي، وجماعة. المقصود: أن سجود التلاوة من جنس الذكر، والخشوع، لا يشترط له الطهارة: التسبيح، والتهليل، والتحميد، والتكبير، وقراءة القرآن عن ظهر قلب لا يشترط لها الطهارة، فهكذا سجود التلاوة. سجود الشكر أيضًا، لا يشترط لهذا كله الطهارة، فلو قرأ عن ظهر قلب، وهو على غير طهارة، أو سبح، أو هلل، أو سجد للتلاوة؛ لا حرج، تقول عائشة -رضي الله عنها-: \"كان النبي ﷺ يذكر الله على كل أحيانه\" والله يقول -جل وعلا-: الذِينَ يَذْكُرُونَ اللهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِهِمْ [آل عمران:191] ولم يشترط في ذلك الطهارة. لكن الجنب لا يقرأ القرآن، فقط الجنب لا يقرأ حتى يغتسل، ولو عن ظهر قلب، أما غير الجنب يقرأ عن ظهر قلب، لكن لا يمس المصحف إلا عن طهارة. والحائض اختلف فيها، هل هي مثل الجنب لا تقرأ حتى تغتسل، أم لا؟ والصواب أنها ليست مثل الجنب، الصواب أنها تقرأ؛ لأن مدتها تطول، وهكذا النفساء مدتها أطول؛ فلا حرج عليهما أن تقرأا عن ظهر قلب؛ لئلا تنسيا القرآن، ولئلا يفوتهما هذا الخير العظيم. لكن لا تقرأ من المصحف، إلا إذا دعت الحاجة للمصحف من وراء القفازين.. من وراء ساتر، لا بأس، عند الحاجة إلى ذلك، أما الجنب لا، لا يقرأ حتى يغتسل، لا من المصحف، ولا عن ظهر قلب. وأما التسبيح، والتهليل، والتكبير، وسجود التلاوة، هذا يقرأ، يفعله الجنب، ويفعله الحائض، ويفعله المحدث، كل ذلك لا حرج عليه؛ لأنه ليس بصلاة، إنما هو ذكر لله، خشوع لله، خضوع لله  هذا هو الصواب في سجود التلاوة، أنه لا يلحق بالصلاة، لكن إذا كان في الصلاة سجد في قراءته في الصلاة، يكبر عند الخفض والرفع؛ لأن الرسول ﷺ كان في الصلاة إذا خفض كبر، وإذا رفع كبر، يكبر في كل خفض، ورفع -عليه الصلاة والسلام- في سجوده، فإذا سجد في الصلاة في قراءته في الصلاة؛ فإنه يكبر عند الخفض، ويكبر عند الرفع. المقدم: جزاكم الله خيرًا.  الشيخ: وفق الله الجميع. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/15363/ما-حكم-التكبير-والتسليم-في-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_759/nour_75907.mp3","categories":["سجود التلاوة والشكر"]},{"id":16698,"question":"بعد هذا رسالة وصلت إلى البرنامج من الأخت المستمعة (أ. ب. ت) من مكة المكرمة، أختنا تسأل عن صفة سجود الشكر؟ جزاكم الله خيرًا.","title":"صفة سجود الشكر","answer":"الجواب: سجود الشكر مثل سجود الصلاة، ومثل سجود التلاوة إذا بشر بشيء يسره؛ سجد لله شكرًا، وقال فيه: سبحان ربي الأعلى، سبحان ربي الأعلى، وحمد ربه  وأثنى عليه، ودعا ربه أن الله يبارك له فيما يسر الله له، ويجود عليه من فضله بما ينفعه في الدنيا والآخرة، حتى ولو كان على غير وضوء، مثل سجود التلاوة لا يشترط له الوضوء على الصحيح، فإنه إذا بشر قد يبشر، وليس على وضوء، وقد يقرأ وهو ليس على وضوء، يقرأ عن ظهر قلب، فإذا مر بالسجدة؛ سجد، وإن كان على غير وضوء على الصحيح. وهكذا إذا بشر بولد، أو فتح للمسلمين ضد عدوهم، أو شفاء مريض، وسجد لله شكرًا؛ فلا حرج عليه، وإن كان على غير وضوء، ويقول في سجوده مثلما يقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، يدعو ربه في سجوده، ويحمده، ويثني عليه لما يسر الله له من النعمة العظيمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15461/صفة-سجود-الشكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82011.mp3","categories":["سجود التلاوة والشكر"]},{"id":16699,"question":"بعد هذا رسالة وصلت إلى البرنامج من الأخت المستمعة (أ. ب. ت) من مكة المكرمة، أختنا تسأل عن صفة سجود الشكر؟ جزاكم الله خيرًا.","title":"صفة سجود الشكر","answer":"الجواب: سجود الشكر مثل سجود الصلاة، ومثل سجود التلاوة إذا بشر بشيء يسره؛ سجد لله شكرًا، وقال فيه: سبحان ربي الأعلى، سبحان ربي الأعلى، وحمد ربه  وأثنى عليه، ودعا ربه أن الله يبارك له فيما يسر الله له، ويجود عليه من فضله بما ينفعه في الدنيا والآخرة، حتى ولو كان على غير وضوء، مثل سجود التلاوة لا يشترط له الوضوء على الصحيح، فإنه إذا بشر قد يبشر، وليس على وضوء، وقد يقرأ وهو ليس على وضوء، يقرأ عن ظهر قلب، فإذا مر بالسجدة؛ سجد، وإن كان على غير وضوء على الصحيح. وهكذا إذا بشر بولد، أو فتح للمسلمين ضد عدوهم، أو شفاء مريض، وسجد لله شكرًا؛ فلا حرج عليه، وإن كان على غير وضوء، ويقول في سجوده مثلما يقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، يدعو ربه في سجوده، ويحمده، ويثني عليه لما يسر الله له من النعمة العظيمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15461/صفة-سجود-الشكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82011.mp3","categories":["سجود التلاوة والشكر"]},{"id":16737,"question":"كيف يكون سجود الشكر؟","title":"كيفية سجود الشكر والتلاوة","answer":"الجواب: سجود الشكر مثل سجود الصلاة، وهكذا سجود التلاوة مثل سجود الصلاة، كما تقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، وتدعو هكذا في سجود التلاوة وسجود الشكر، تحمد الله في سجود الشكر على ما أنعم به عليك، تقول: الحمد لله على ما أنعم به علي من نعمة كذا، والشكر لله، تقول: سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، مثلما تفعل في سجود الصلاة، ولكن مع هذا في الشكر تزيد، تحمد الله، تثني عليه، تشكره على ما أعطاك من النعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15484/كيفية-سجود-الشكر-والتلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71809.mp3","categories":["سجود التلاوة والشكر"]},{"id":17041,"question":"هل تشرع جلسة الاستراحة عند سجود التلاوة أثناء الصلاة؟","title":"حكم جلسة الاستراحة عند سجود التلاوة","answer":"الجواب: جلوس الاستراحة بعد الأولى، وبعد الثالثة في الرباعية، وبعد الأولى في الثنائية، كان النبي ﷺ يجلس قليلًا استراحة خفيفة، جلسة خفيفة، وربما تركها. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15829/حكم-جلسة-الاستراحة-عند-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58718.mp3","categories":["سجود التلاوة والشكر"]},{"id":17225,"question":"السائلة أم سعد، تقول: سماحة الشيخ، إذا استمعت إلى المذياع وهو يقرأ القرآن، فمر القارئ بسجدة، هل أسجد معه، أم لا؟","title":"سجود سامع التلاوة متعلق بسجود القارئ","answer":"الجواب: إن سجد فاسجدي، إذا سجد القاري وأنت تسمعين فاسجدي، وإذا ما سجد لا تسجدي. نعم.","link":"https://binbaz.org.sa/fatwas/16051/سجود-سامع-التلاوة-متعلق-بسجود-القارى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59102.mp3","categories":["سجود التلاوة والشكر"]},{"id":17543,"question":"من سلطنة عمان رسالة بعثت بها الأخت (ص. خ) تسأل جمعًا من الأسئلة في أحدها تقول: ما كيفية سجود التلاوة؟","title":"كيفية سجود التلاوة","answer":"الجواب: سجود التلاوة مثل سجود الصلاة سواء، سجود التلاوة وسجود الشكر مثل سجود الصلاة، وهكذا سجود السهو يقول فيه: (سبحان ربي الأعلى، سبحان ربي الأعلى، سبحان ربي الأعلى) وإن قال اللهم لك سجدت وبك آمنت ولك أسلمت، سجد وجهي للذي خلقه وصوره وشق سمعه وبصره بحوله وقوته، تبارك الله أحسن الخالقين، فحسن؛ لأن هذا مشروع في سجود الصلاة فهكذا سجود التلاوة وسجود السهو أيضًا، لكن لا يشترط له الطهارة بخلاف سجود السهو فلا بد من الطهارة. أما سجود التلاوة وسجود الشكر فهذان السجودان لا يشترط لهما الطهارة على الصحيح، بل يجوز للقاري الذي ليس على وضوء إذا مر بالسجدة أن يسجد على الصحيح، وهكذا من كان على غير وضوء وبشر بأمر عظيم شرع له سجود الشكر وإن كان على غير طهارة، ولما جاء خبر قتل مسيلمة عدو الله إلى أبي بكر الصديق  سجد لله شكرًا .\nفالمقصود أن سجود الشكر وسجود التلاوة الصحيح لا يشترط لهما الطهارة بخلاف سجود السهو فإنه لا بد من طهارة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16474/كيفية-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83806.mp3","categories":["سجود التلاوة والشكر"]},{"id":17636,"question":"تقول: إذا مرت بآية سجدة سجدت لكنها لا تدري ماذا تقول في سجود التلاوة فاشرحوا لها ذلك جزاكم الله خيرًا؟","title":"ما يقال في سجود التلاوة","answer":"الجواب: حكمه حكم سجود الصلاة الرجل والمرأة جميعًا في سجود التلاوة، يقول فيه: سبحان ربي الأعلى سبحان ربي الأعلى ثلاث مرات أفضل أو خمس والواجب مرة واحدة، وإذا زاد ثلاث أو خمس أو أربع أو ست كله طيب هذا هو الأفضل ويدعو ....... السجود مثلما تقدم: اللهم اغفر لي ذنبي وكان النبي ﷺ يدعو في سجوده يقول: اللهم اغفر لي ذنبي كله دقه وجله وأوله وآخره وعلانيته وسره، هذا من دعاء النبي ﷺ وإذا دعا أيضًا بغير هذا مثل اللهم لك سجدت وبك آمنت ولك أسلمت سجد وجهي للذي خلقه وصوره وشق سمعه وبصره بحوله وقوته تبارك الله أحسن الخالقين هذا فعله النبي ﷺ، ثناء على الله وخضوع له . نعم.","link":"https://binbaz.org.sa/fatwas/16575/ما-يقال-في-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84413.mp3","categories":["سجود التلاوة والشكر"]},{"id":17949,"question":"سماحة الشيخ! هذه رسالة وصلت من المنطقة الشرقية من الأخت المستمعة (م. ص. س) تقول سماحة الشيخ: قراءة القرآن للمرأة هل يلزمها حجاب أم لا؟ وإذا مرت بآية سجدة هل تتحجب؟","title":"هل يلزم الحجاب لقراءة القرآن وسجود التلاوة؟","answer":"الجواب: لا يلزمها حجاب، إذا كان ما عندها أجنبي لا، ولو طرحت خمارها عن رأسها تقرأ لا بأس، إذا كان ما عندها أجنبي، وتسجد إذا مرت بسجود تلاوة تسجد، هذا هو الأفضل، وإذا كان مرت بآية سجود كونها تجعل الخمار على رأسها أفضل عند السجود. نعم.","link":"https://binbaz.org.sa/fatwas/16954/هل-يلزم-الحجاب-لقراءة-القران-وسجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59828.mp3","categories":["سجود التلاوة والشكر","ستر العورة للمصلي","قضايا المرأة"]},{"id":18721,"question":"هل يلزم المرأة الاحتجاب عند سجود التلاوة، وإذا كانت التلاوة خارج الصلاة، فما الحكم؟","title":"حكم تستر المرأة عند سجود التلاوة","answer":"الجواب: تسجد ولا يحتاج حجاب إذا كان ما عندها أجنبي، تسجد مثلما تسجد في الصلاة إذا قرأت آية السجود، تسجد في بيتها في صلاتها في الفريضة، وفي النافلة كالرجل، ولا حاجة إلى حجابه، حجاب الوجه، لكن تستر بدنها كالصلاة هذا هو الأفضل، وإلا سجود التلاوة ليس صلاة، لكن إذا كانت في الصلاة لا بد من تسترها، تستر شعرها وبدنها كله إلا وجهها، والكفين فيهما الخلاف، وسترهما أولى الكفين.  أما بقية البدن تستره في الصلاة تستر شعرها، وبدنها، وقدميها، وسجود التلاوة في الصلاة من جنس الصلاة، بعض من الصلاة تستر بدنها فيه. أما إذا كان سجود التلاوة خارج الصلاة فالأمر فيه أوسع، لو سجدت، ولم تغط رأسها، أو تغط قدميها صح سجودها؛ لأن سجود التلاوة في خارج الصلاة ليس صلاة، وهكذا سجود الشكر إنما هو خضوع لله، وليس له حكم الصلاة، فإذا قرأ القاري خارج الصلاة وهو على غير وضوء يستحب له السجود، وهكذا المرأة إذا قرأت خارج الصلاة وهي على غير وضوء لها السجود، يستحب لها السجود سجود التلاوة، نعم؛ لأنه ليس له حكم الصلاة على الصحيح، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17829/حكم-تستر-المراة-عند-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78816.mp3","categories":["سجود التلاوة والشكر","القرآن وعلومه","قضايا المرأة"]},{"id":19001,"question":"عند قراءة القرآن يكون هناك سجدة، فكم مرة نسجد؟ وماذا نقول؟ هل نقول فقط: سبحان ربي الأعلى ثلاث مرات؟ أم أن هناك أدعية أخرى؟ جزاكم الله خيرًا.","title":"صفة سجود التلاوة","answer":"الجواب: سجود السهو مثل سجود الصلاة سواء، يقول في سجود السهو، وفي سجود التلاوة؛ مثلما يقول في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، ويدعو فيه، ويقول: اللهم لك سجدت وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره بحوله وقوته، تبارك الله أحسن الخالقين كان يقول هذا في سجوده عليه الصلاة والسلام. هذا يقال في سجود التلاوة، وسجود السهو، وفي سجود الصلاة، ومن الدعاء اللهم اغفر لي ذنبي كله؛ دقه وجله، وأوله وآخره، وعلانيته وسره اللهم اغفر لي ولوالدي، اللهم إني أسألك رضاك والجنة، وأعوذ بك من سخطك والنار، وما أشبه ذلك من الدعوات الطيبة. المقصود أن سجود السهو مثل سجود الصلاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18162/صفة-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_795/nour_79503.mp3","categories":["سجود التلاوة والشكر"]},{"id":19093,"question":"تسأل أختنا وتقول: ما حكم السهو في هذه المواضع قراءة الفاتحة في موضع التحيات أو العكس؟","title":"حكم من أتى بذكر في الصلاة في غير محله","answer":"الجواب: لا شيء في ذلك، الصلاة صحيحة. ولا حرج في ذلك، وإذا سجد للسهو يكون أفضل. إذا سجد للسهو إذا كان إمامًا أو منفردًا وسجد للسهو يكون أفضل، وإلا ما يلزمه. المقدم: وإلا لا يلزمه. الشيخ: لأنه قول مشروع في غير محله، قول مشروع في الصلاة لكن أتى به في غير محله، فإذا سجد للسهو كان ذلك أفضل، وإلا فلا حرج. نعم. المقدم: جزاكم الله خيرًا. قول: الله أكبر بدلًا من سمع الله لمن حمده؟ الشيخ: هذا سهو والصلاة صحيحة، وعلى الإمام إذا كان فعله الإمام سجود السهو أو المنفرد. أما إذا كان فعله المأموم قال: الله أكبر بدل ربنا ولك الحمد فلا عليه شيء؛ لأن المأموم تابع لإمامه، إذا كان دخل معه من أول الصلاة ليس عليه شيء، يتحمل عنه الإمام هذا السهو. لكن إذا كان المأموم سها في ما انفرد به إذا كان قد فاته بعض الصلاة أي: المسبوق، فهذا إذا سها في شيء وهو مسبوق مع إمامه، أو سلم مع إمامه ساهيًا ثم انتبه أو سها فيما انفرد به، هذا يسجد للسهو. وأما سهوه مع إمامه من أول الصلاة وهو معه من أول الصلاة، هذا يتحمله عنه الإمام. إذا سهو سهوًا لا يخل بالفعل مثل سها عن سبحان ربي الأعلى أو سبحان ربي العظيم، أو قال بدل ربنا ولك الحمد: سمع الله لمن حمده، أو الله أكبر، هذا لا يضر ولا سجود عليه لأنه تابع. أما إذا سها في الركوع أو في السجود لابد أن يأتي به، إذا سها كان يهوجس وركع إمامه وهو لم يركع ثم انتبه يركع ويلحق إمامه وهكذا في السجود هذه أركان لابد منها. لكن إذا سها في الأشياء التي هي تعتبر واجبات لكنها قولية، سها فيها المأموم فلا شيء عليه أو سها في التشهد الأول مثلاً ما أتى به فلا شيء عليه؛ لأنه تابع لإمامه. أما في الأركان لابد منها، التشهد الأخير ركن لابد يأتي به لو سها ولم يأت به مع الإمام ثم انتبه يأتي به قبل أن يسلم ثم يسلم بعد ذلك، أو انتبه بعد السلام يعود بنية الصلاة ويأتي بالتشهد ثم يسلم. نعم. المقدم: وبالنسبة للمنفرد أو المرأة في بيتها؟ الشيخ: عليهم سجود السهو إذا كان في مثل: (سبحان ربي الأعلى) في الواجبات يعني، إذا كان منفردًا رجل أو امرأة في صلاة منفردة إذا سها في الواجبات مثل ترك (سبحان ربي الأعلى) أو (سبحان ربي العظيم) في الركوع أو (ربنا ولك الحمد) سها عنها، يسجد للسهو قبل أن يسلم سجدتين أو ترك التشهد الأول قام إلى الثالثة ناسي التشهد الأول، هذا يسجد للسهو سجدتين قبل أن يسلم، كما فعله النبي عليه الصلاة والسلام. المقدم: وإذا قال ألفاظًا مكان ألفاظ أخرى. الشيخ: لا يضر. المقدم: لا يضر. الشيخ: لكن إن سجد وهي مشروعة فلا بأس مثل قرأ التحيات وهو جالس أو قرأ الحمد وهو جالس ناسي، إذا سجد للسهو يكون أفضل لا تبطل الصلاة ولا يجب، لأنه قول مشروع أتى به في غير موضعه. ليس بمنكر في الصلاة. نعم. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/18262/حكم-من-اتى-بذكر-في-الصلاة-في-غير-محله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_930/nour_93007.mp3","categories":["سجود التلاوة والشكر","سجود السهو","الأدعية والأذكار"]},{"id":19098,"question":"ما هو الدعاء المستحب في سجود التلاوة؟","title":"الدعاء المستحب في سجود التلاوة","answer":"الجواب: مثل الدعاء في سجود الصلاة، يستحب له أن يدعو بما تيسر من الدعوات الطيبة، والدعاء المأثور أفضل مثل اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره، اللهم يا مقلب القلوب ثبت قلبي على دينك، أو يا مصرف القلوب صرف قلبي على طاعتك، فالدعوات الطيبة المأثورة أولى من غيرها، مثل: اللهم آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار، يقولها لا على سبيل القراءة بل على سبيل الدعاء. وهكذا كونه يدعو لوالديه، ولأقاربه المسلمين، يدعو لذريته، يسأل الله من فضله رزقًا حلالًا، أو زوجة صالحة، أو زوجًا صالحًا إذا كانت امرأة أو ما أشبه ذلك، يدعو بما تيسر، يقول النبي ﷺ في الحديث الصحيح: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقمن أن يستجاب لكم، يعني: حري أن يستجاب لكم، رواه مسلم في صحيحه. وقال عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء، رواه مسلم أيضًا، فهذا يدل على شرعية الإكثار من الدعاء في السجود ولا يتعين دعاء مخصوص، بل يدعو المؤمن والمؤمنة بما يسر الله لهما من الدعاء فيما يحتاجان إليه من الدعوات التي ليس فيها إثم ولا قطيعة رحم، بل دعاء مباح. المقدم: جزاكم الله خيرًا. الشيخ: نعم. المقدم: بارك الله فيكم، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/18302/الدعاء-المستحب-في-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88409.mp3","categories":["سجود التلاوة والشكر","الأدعية والأذكار"]},{"id":19100,"question":"الأخت المستمعة (ب. ع. ح) من القصيم بريدة بعثت برسالة وضمنتها أربعة أسئلة، في سؤالها الأول تسأل وتقول: ما هو سجود الشكر، وهل يسجد في صلاة أم بدون صلاة؟ وهل حكمه حكم سجود الصلاة من حيث الطهارة وستر العورة وغيرها أم لا؟ وما هو الدعاء المستحب فيها؟","title":"ما معنى سجود الشكر وحكمه؟ وما دعاؤه؟","answer":"الجواب: سجود الشكر هو السجود من أجل نعمة عامة ساقها الله للمسلمين، أو نعمة خاصة ساقها الله للشخص، كوجود ولد له، وكسلامته من حادث، ونحو ذلك، ولما بلغ الصديق  مقتل مسيلمة الكذاب خر ساجدًا لله  شكرًا لله على نعمة قتل الخبيث، عدو الله مسيلمة الكذاب. فإذا بشر الإنسان بشيء يسره، وسجد لله سبحانه شكرًا فهذا يقال له: سجود الشكر، ويقال فيه ما يقال في سجود الصلاة: سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، ويدعو فيه الإنسان مثل سجود الصلاة سواء. والصحيح أنه لا يشترط له الطهارة، بل هو مثل سجود التلاوة، الصحيح أنهما لا تشترط لهما الطهارة، بل لا مانع من السجود وإن كان على غير طهارة، فإذا صار يتلو القرآن وليس على طهارة ومر بآيات السجدة فإنه يشرع له السجود وإن كان على غير طهارة، وهكذا سجود الشكر ليس له شرط الطهارة، بل يسجد وإن كان على غير طهارة؛ لأنه ليس من جنس الصلاة، بل هو ذل لله واستكانة، وعبادة له سبحانه من جنس الذكر، ومن جنس التسبيح والتهليل، من جنس قراءة القرآن، فليس له شرط الطهارة كما أن القاري من غير المصحف لا يشترط له الطهارة، فهكذا الذاكر والمسبح والمهلل والمستغفر يجوز أن يفعل هذا وإن كان على غير طهارة، هذا هو الصواب، وبعض أهل العلم قال: إنه لا بد من طهارة كالصلاة، ولكنه قول مرجوح ليس عليه دليل . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18300/ما-معنى-سجود-الشكر-وحكمه-وما-دعاوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88407.mp3","categories":["سجود التلاوة والشكر"]},{"id":19361,"question":"تسأل أختنا أيضًا وتقول: أسأل عن سجدة القرآن الكريم هل هي سجدة فقط؟ أم هي ركعة كاملة أي: فاتحة القرآن وسورة قصيرة، وركوع ثم سجود؟","title":"ما صفة سجود التلاوة؟","answer":"الجواب: السجود للتلاوة سجدة فقط سجدة مجردة، إذا مر على آية السجود سجد قال: الله أكبر، وسجد سجدة واحدة في الأرض يقول فيها: سبحان ربي الأعلى، سبحان ربي الأعلى مثلما يقول في سجود الصلاة، وإذا زاد فقال: سجد وجهي للذي خلقه، اللهم لك أسلمت، وبك آمنت، سجد وجهي للذي خلقه وصوره، وشق سمعه، وبصره، بحوله وقوته، تبارك الله أحسن الخالقين كان حسنًا كما يقال في سجود الصلاة سواء. وإذا دعا بدعوات أخرى مع سبحان ربي الأعلى سبحان ربي الأعلى كل ذلك حسن، والمقصود أنها مثل سجود الصلاة يقول فيها ما يقول في سجود الصلاة، ومن ذلك أن يقول: اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره، بحوله وقوته، تبارك الله أحسن الخالقين، فهذا يقال في سجود الصلاة، ويقال في سجود التلاوة، ويقال في سجود السهو، كل ذلك لا بأس به. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18573/ما-صفة-سجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_942/nour_94202.mp3","categories":["سجود التلاوة والشكر"]},{"id":19538,"question":"هذا سائل يقول: قراءة القرآن للمرأة هل يلزمها حجاب أم لا؟ وإذا مرت بآية سجدة هل تتحجب؟","title":"حكم الحجاب للمرأة عند قراءة القرآن وسجود التلاوة","answer":"الجواب: إذا كان ما عندها أحد لا يلزمها حجاب، وإذا مرت بها سجدة تسجد والحمد لله، ولو كانت على غير طهارة هذا الصواب، الصواب أن سجود التلاوة لا يشترط له الطهارة، وهكذا سجود الشكر، فإذا كانت تقرأ وهي على غير طهارة عن ظهر قلب من حفظها، ومرت بالسجدة شرع لها السجود. نعم.","link":"https://binbaz.org.sa/fatwas/18786/حكم-الحجاب-للمراة-عند-قراءة-القران-وسجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94621.mp3","categories":["سجود التلاوة والشكر"]},{"id":19656,"question":"هل تسجد الحائض سجود التلاوة وسجود الشكر؟","title":"حكم سجود التلاوة والشكر للحائض","answer":"الجواب: لا بأس؛ لأنها لا يشترط لها الطهارة سجود التلاوة وسجود الشكر لا يشترط لهما الطهارة، فلها أن تسجد إذا قرأت. نعم.","link":"https://binbaz.org.sa/fatwas/18940/حكم-سجود-التلاوة-والشكر-للحاىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95010.mp3","categories":["سجود التلاوة والشكر"]}]
